import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.l1I-fhud.js";const g=JSON.parse('{"title":"Ref grammar","description":"","frontmatter":{},"headers":[],"relativePath":"reference/refs.md","filePath":"reference/refs.md"}'),c={name:"reference/refs.md"};function i(d,e,r,n,l,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="ref-grammar" tabindex="-1">Ref grammar <a class="header-anchor" href="#ref-grammar" aria-label="Permalink to &quot;Ref grammar&quot;">​</a></h1><p>A <strong>ref</strong> names <em>where</em> a package comes from. One grammar covers all sources; the impl is picked by shape.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./dir                                         local (dev loop)</span></span>
<span class="line"><span>git:9aia/bupha//libraries/ci-gate#main   git + in-repo subdir + ref</span></span>
<span class="line"><span>https://…/ci-gate-0.2.0.tgz#sha256:&lt;hex&gt;        tarball (+ digest pin)</span></span>
<span class="line"><span>cf:&lt;account&gt;/&lt;bucket&gt;/&lt;name&gt;@&lt;ver&gt;             Cloudflare registry</span></span>
<span class="line"><span>9aia:&lt;name&gt;@&lt;ver&gt;                              named registry (config)</span></span>
<span class="line"><span>9aia:@scope/&lt;name&gt;@&lt;ver&gt;                        named registry, scoped</span></span></code></pre></div><h2 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h2><ul><li><code>//subdir</code> splits the repo from the in-repo path (go-getter convention) — required because nested groups make bare <code>a/b/c/d</code> ambiguous. Without <code>//</code>, a two-segment prefix is the repo and the remainder is the in-repo path.</li><li><code>#ref</code> is a branch, tag, sha, or <strong>relative rev</strong> (<code>HEAD~2</code>, <code>main^</code>) — the version pin. The resolved commit sha is recorded in the store regardless. Revs can&#39;t start with <code>-</code> or contain whitespace, <code>..</code>, or <code>//</code>, so a ref can&#39;t smuggle git options.</li><li>Clone URLs are allowlisted: <code>https</code>, <code>http</code>, <code>ssh</code>, <code>git</code>, <code>file</code>, and scp-style <code>git@host:…</code>. Anything else is rejected.</li><li>Fetches run with <code>GIT_TERMINAL_PROMPT=0</code> — a credential prompt fails the fetch instead of hanging.</li><li><code>org/repo</code> defaults to <code>github.com</code>; <code>host/org/repo</code> becomes <code>https://host/org/repo</code>; <code>git@host:…</code> and <code>ssh://</code>/<code>file://</code> pass through.</li></ul><h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><ul><li>A <code>.tgz</code> / <code>.tar.gz</code> URL over <code>http(s)</code>, with an optional <code>#sha256:&lt;hex&gt;</code> pin — verified against the downloaded bytes before unpack. An <code>http://</code> URL <strong>without</strong> a pin fetches cleartext and prints a warning; prefer <code>https://</code> or pin the digest.</li></ul><h2 id="cloudflare-registry" tabindex="-1">Cloudflare registry <a class="header-anchor" href="#cloudflare-registry" aria-label="Permalink to &quot;Cloudflare registry&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cf:&lt;account&gt;/&lt;bucket…&gt;/&lt;name&gt;@&lt;version&gt;</span></span></code></pre></div><p>The address derives the base URL: a full <code>http(s)://…</code> passes through (local / dev registries), a first segment with <strong>no dot</strong> is a <code>workers.dev</code> subdomain, and later segments are a path prefix.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cf:9aia/myrepo/ci-gate@0.2.0        → https://9aia.workers.dev/myrepo</span></span>
<span class="line"><span>cf:reg.example.com/ci-gate@0.2.0    → https://reg.example.com</span></span>
<span class="line"><span>cf:http://127.0.0.1:8903/w@1.0.0    → http://127.0.0.1:8903</span></span></code></pre></div><p><code>install</code> fetches <code>&lt;base&gt;/index.json</code>, finds <code>name@version</code>, pulls the tarball (<code>&lt;base&gt;/&lt;file&gt;</code>), unpacks it, and <strong>verifies the unpacked payload against the index&#39;s recorded <code>dir_digest</code></strong> — a mismatched payload fails the install. Note the digest covers the payload <em>dir</em>, not the tarball bytes, so it can&#39;t be checked at transport (see <a href="/tamias/explanation/security.html">Security model</a>).</p><h2 id="named-registry" tabindex="-1">Named registry <a class="header-anchor" href="#named-registry" aria-label="Permalink to &quot;Named registry&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;label&gt;:&lt;name&gt;@&lt;version&gt;</span></span>
<span class="line"><span>&lt;label&gt;:@scope/&lt;name&gt;@&lt;version&gt;</span></span></code></pre></div><p><code>&lt;label&gt;</code> resolves against the <em>effective</em> config&#39;s <code>registries</code> map — the user-level <code>~/.config/tamias/tamias.*</code> base overlaid by the cwd <code>tamias.*</code> (same layering as <code>publish</code>/<code>search</code>). An entry&#39;s <code>id</code> (uuid or slug-safe string, <code>registry add --id</code>) matches <strong>before</strong> the map key, so refs can pin a stable id across renames. Only <code>http</code>/<code>cf</code> kind registries are installable — a <code>local</code> (unserved dir) registry errors with a pointer at <code>tamias registry serve</code>. An unknown label is a hard error (<code>unknown registry &#39;&lt;label&gt;&#39;</code>), never a silent path fallback.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tamias install 9aia:cicada-demo@0.1.0</span></span>
<span class="line"><span>tamias install 018f3c2e-…:@acme/scoped@2.0.0</span></span></code></pre></div><p><code>@&lt;version&gt;</code> is required — there is no &quot;latest&quot; resolution. Fetching goes through the same path as <code>cf:</code> (index lookup → payload-digest + signature verification → tarball fetch), and the store record keeps the verbatim <code>&lt;label&gt;:…</code> ref as provenance. Bearer auth uses the registry&#39;s <code>token_env</code> (env var <em>name</em>, falling back to <code>TAMIAS_REGISTRY_TOKEN</code>). A <code>&lt;label&gt;:</code> that matches a reserved kind prefix (<code>git:</code>, <code>cf:</code>, <code>http(s):</code>, <code>ssh:</code>, <code>fs:</code>, <code>file:</code>) is never a registry ref, and single-letter labels are excluded so Windows drive letters (<code>C:\\…</code>) can&#39;t false-positive.</p><p>The same refs work in a project manifest&#39;s <code>deps:</code> — <code>tamias sync</code> reconciles them like any other ref.</p><h2 id="local" tabindex="-1">Local <a class="header-anchor" href="#local" aria-label="Permalink to &quot;Local&quot;">​</a></h2><ul><li><code>./x</code>, <code>../x</code>, <code>~/x</code>, <code>/x</code>, or a bare path.</li></ul>`,20)])])}const m=a(c,[["render",i]]);export{g as __pageData,m as default};
